  "inlineSchema": "// schema.prisma\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../lib/generated/prisma\"\n}\n\nenum Role {\n  ADMIN\n  MANAGER\n  CASHIER\n  CUSTOMER\n  AFFILIATE\n}\n\nenum OrderStatus {\n  PENDING // Just created\n  CONFIRMED // Confirmed and in preparation\n  IN_TRANSIT // Out for delivery\n  DELIVERED // Successfully delivered\n  CANCELLED // Cancelled by user or admin\n}\n\nenum OrderType {\n  ONLINE\n  POS\n}\n\nenum PaymentStatus {\n  PENDING\n  SUCCESS\n  FAILED\n}\n\nenum PaymentMethod {\n  PAYSTACK\n  CASH\n  TRANSFER\n}\n\nenum DeliveryType {\n  DELIVERY\n  PICKUP\n}\n\nmodel User {\n  id           String   @id @default(uuid())\n  email        String   @unique\n  passwordHash String\n  name         String?\n  phone        String?\n  role         Role     @default(CUSTOMER)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n  isActive     Boolean  @default(true)\n\n  orders      Order[]      @relation(\"CustomerOrders\")\n  addresses   Address[]\n  affiliate   Affiliate?   @relation(\"UserAffiliate\")\n  posSessions PosSession[] @relation(\"StaffSessions\")\n  cartItems   CartItem[]\n}\n\nmodel Affiliate {\n  userId        String   @id\n  approved      Boolean  @default(false)\n  referralCode  String   @unique\n  totalEarnings Float    @default(0)\n  createdAt     DateTime @default(now())\n\n  user        User         @relation(\"UserAffiliate\", fields: [userId], references: [id])\n  referrals   Referral[]\n  commissions Commission[]\n}\n\nmodel Referral {\n  id           String   @id @default(uuid())\n  affiliateId  String\n  referredUser String   @unique\n  referredAt   DateTime @default(now())\n\n  affiliate Affiliate @relation(fields: [affiliateId], references: [userId])\n}\n\nmodel Address {\n  id         String   @id @default(uuid())\n  userId     String\n  label      String // e.g., \"Home\", \"Work\", \"Mum's House\"\n  street     String\n  city       String\n  state      String\n  postalCode String?\n  country    String   @default(\"Nigeria\")\n  isDefault  Boolean  @default(false)\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  user   User    @relation(fields: [userId], references: [id])\n  orders Order[]\n}\n\nmodel Commission {\n  id          String   @id @default(uuid())\n  affiliateId String\n  orderId     String   @unique\n  amount      Float\n  paid        Boolean  @default(false)\n  createdAt   DateTime @default(now())\n\n  affiliate Affiliate @relation(fields: [affiliateId], references: [userId])\n  order     Order     @relation(fields: [orderId], references: [id], onDelete: Cascade)\n}\n\nmodel Category {\n  id        Int      @id @default(autoincrement())\n  name      String   @unique\n  createdAt DateTime @default(now())\n\n  products Product[]\n}\n\nmodel Product {\n  id          Int       @id @default(autoincrement())\n  name        String\n  description String?\n  price       Float\n  costPrice   Float?\n  sku         String?   @unique\n  isActive    Boolean   @default(true)\n  categoryId  Int\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n  deletedAt   DateTime?\n\n  category   Category       @relation(fields: [categoryId], references: [id])\n  images     ProductImage[]\n  inventory  Inventory?\n  orderItems OrderItem[]\n  cartItems  CartItem[]\n  posItems   PosItem[]\n}\n\nmodel ProductImage {\n  id        Int      @id @default(autoincrement())\n  url       String\n  productId Int\n  createdAt DateTime @default(now())\n\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n}\n\nmodel Inventory {\n  id            Int      @id @default(autoincrement())\n  productId     Int      @unique\n  quantity      Int\n  lowStockAlert Int      @default(5)\n  updatedAt     DateTime @updatedAt\n\n  product      Product                @relation(fields: [productId], references: [id])\n  transactions InventoryTransaction[]\n}\n\nmodel InventoryTransaction {\n  id          Int      @id @default(autoincrement())\n  inventoryId Int\n  change      Int // positive = restock, negative = sale\n  reason      String?\n  createdAt   DateTime @default(now())\n\n  inventory Inventory @relation(fields: [inventoryId], references: [id])\n}\n\nmodel Order {\n  id            String        @id @default(uuid())\n  customerId    String\n  addressId     String?\n  affiliateCode String? // if referred via affiliate link\n  status        OrderStatus   @default(PENDING) // e.g., CONFIRMED, DELIVERED\n  orderType     String        @default(\"ONLINE\") // ONLINE or POS\n  paymentStatus PaymentStatus @default(PENDING)\n  deliveryType  DeliveryType? @default(DELIVERY) // DELIVERY or PICKUP\n  deliveryAddr  String?\n  totalAmount   Float\n  taxAmount     Float?\n  deliveryFee   Float?\n  orderNotes    String?\n  placedAt      DateTime      @default(now())\n  updatedAt     DateTime      @updatedAt\n\n  customer   User        @relation(\"CustomerOrders\", fields: [customerId], references: [id])\n  address    Address?    @relation(fields: [addressId], references: [id])\n  items      OrderItem[]\n  payment    Payment?\n  commission Commission?\n}\n\nmodel OrderItem {\n  id        Int    @id @default(autoincrement())\n  orderId   String\n  productId Int\n  quantity  Int\n  unitPrice Float\n\n  order   Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [productId], references: [id])\n}\n\nmodel Payment {\n  id            String        @id @default(uuid())\n  orderId       String        @unique\n  method        PaymentMethod @default(PAYSTACK) // e.g. PAYSTACK, FLUTTERWAVE, CASH\n  amount        Float\n  status        PaymentStatus @default(PENDING) // PENDING, SUCCESS, FAILED\n  transactionId String?\n  paidAt        DateTime?\n  createdAt     DateTime      @default(now())\n\n  order Order @relation(fields: [orderId], references: [id], onDelete: Cascade)\n}\n\nmodel PosSession {\n  id       String    @id @default(uuid())\n  staffId  String\n  openedAt DateTime  @default(now())\n  closedAt DateTime?\n\n  staff    User      @relation(\"StaffSessions\", fields: [staffId], references: [id])\n  posItems PosItem[]\n}\n\nmodel PosItem {\n  id        Int    @id @default(autoincrement())\n  sessionId String\n  productId Int\n  quantity  Int\n  unitPrice Float\n\n  session PosSession @relation(fields: [sessionId], references: [id])\n  product Product    @relation(fields: [productId], references: [id])\n}\n\nmodel CartItem {\n  id        Int      @id @default(autoincrement())\n  userId    String\n  productId Int\n  quantity  Int      @default(1)\n  addedAt   DateTime @default(now())\n\n  user    User    @relation(fields: [userId], references: [id])\n  product Product @relation(fields: [productId], references: [id])\n\n  @@unique([userId, productId])\n}\n\nmodel Setting {\n  id          Int     @id @default(autoincrement())\n  key         String  @unique\n  value       String\n  description String?\n}\n",
